const b = $input.first().json.body;
const fail = (error) => [{json:{ok:false,status:'failed',http_status:422,error}}];
if (!b || typeof b !== 'object' || Array.isArray(b)) return fail('Body harus JSON object');
for (const key of ['notification_id','to','subject','html']) {
  if (typeof b[key] !== 'string' || !b[key].trim()) return fail('Field tidak valid: '+key);
}
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(b.to)) return fail('Alamat email tidak valid');
const text = typeof b.text === 'string' ? b.text : '';
const unsub = typeof b.unsubscribe_url === 'string' && /^https:\/\/[^\s<>]+$/.test(b.unsubscribe_url) ? b.unsubscribe_url : '';
if (b.subject.length > 200 || b.html.length > 60000 || text.length > 20000 || b.notification_id.length > 150) return fail('Payload terlalu panjang');
const sender = typeof b.sender_name === 'string' && b.sender_name.trim() ? b.sender_name.trim().slice(0, 80) : 'CRM Maiharta';
return [{json:{ok:true,notification_id:b.notification_id,to:b.to,subject:b.subject,html:b.html,text,unsubscribe_url:unsub,sender_name:sender}}];

const v = $('Validasi payload').first().json;
const profile = $input.first().json;
const from = profile && profile.body && profile.body.emailAddress;
if (!from) return [{json:{raw:'', error:'Profil Gmail tidak terbaca. Periksa credential Gmail OAuth2.'}}];
const enc = (s) => '=?UTF-8?B?' + Buffer.from(s, 'utf8').toString('base64') + '?=';
const b64 = (s) => Buffer.from(s, 'utf8').toString('base64').replace(/.{76}/g, '$&\r\n');
const text = v.text || v.subject;
const boundary = 'crm-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
const headers = [
  'From: ' + enc(v.sender_name) + ' <' + from + '>',
  'To: <' + v.to + '>',
  'Reply-To: <' + from + '>',
  'Subject: ' + enc(v.subject),
  'Date: ' + new Date().toUTCString(),
  'MIME-Version: 1.0',
  'X-Entity-Ref-ID: ' + v.notification_id.replace(/[^A-Za-z0-9-]/g, ''),
];
if (v.unsubscribe_url) headers.push('List-Unsubscribe: <' + v.unsubscribe_url + '>');
headers.push('Content-Type: multipart/alternative; boundary="' + boundary + '"');
const mime = headers.concat([
  '', '--' + boundary, 'Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', b64(text),
  '--' + boundary, 'Content-Type: text/html; charset=UTF-8', 'Content-Transfer-Encoding: base64', '', b64(v.html),
  '--' + boundary + '--', '',
]).join('\r\n');
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{json:{raw}}];

const r = $input.first().json;
const body = r.body || {};
const id = typeof body.id === 'string' ? body.id : '';
const ok = r.statusCode >= 200 && r.statusCode < 300 && id.trim().length > 0;
return [{json: ok ? {ok:true,status:'accepted',http_status:202,notification_id:$('Validasi payload').first().json.notification_id,message_id:id} : {ok:false,status:'failed',http_status:502,error:'Gmail belum mengonfirmasi pengiriman. Periksa credential Gmail OAuth2 di node Profil Gmail & Kirim via Gmail API.'}}];
